using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class DetailAudit {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string O=>R+"/Docs/검수/2026-11-06_B5_FullLayout/";
 static Transform Root(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty)throw new Exception("Saved edit scene required");return s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;}
 static string PathOf(Transform t)=>t.parent?PathOf(t.parent)+"/"+t.name:t.name;
 public static object Props(){var root=Root();Physics.SyncTransforms();var findings=new List<object>();var boxes=root.Find("B5_FullLayout_Implementation/Outer_Caverns_Props").GetComponentsInChildren<BoxCollider>().Where(c=>c.enabled).ToArray();foreach(var box in boxes)foreach(var c in Physics.OverlapBox(box.bounds.center,box.bounds.extents,Quaternion.identity,~0,QueryTriggerInteraction.Ignore).Where(c=>c!=box&&!c.transform.IsChildOf(box.transform)&&c.transform.IsChildOf(root)&&!c.name.Contains("Floor"))){Vector3 direction;float depth;if(Physics.ComputePenetration(box,box.transform.position,box.transform.rotation,c,c.transform.position,c.transform.rotation,out direction,out depth)&&depth>.035f)findings.Add(new{box=PathOf(box.transform),other=PathOf(c.transform),depth});}File.WriteAllText(O+"outer_prop_check.json",JsonConvert.SerializeObject(findings,Formatting.Indented));return new{testedBoxes=boxes.Length,findings};}
 public static object Doors(){var root=Root();var doors=root.Find("Pocket_Doors_Open");var results=new List<object>();var s=SceneManager.GetActiveScene();try{foreach(Transform door in doors){Func<bool> blocked=()=>Physics.OverlapCapsule(door.position+Vector3.up*.34f,door.position+Vector3.up*1.48f,.28f,~0,QueryTriggerInteraction.Ignore).Any(c=>c.transform.IsChildOf(door)&&!c.name.Contains("Threshold"));Physics.SyncTransforms();bool openClear=!blocked();var moved=new Dictionary<Transform,Vector3>();foreach(var mf in door.GetComponentsInChildren<MeshFilter>())if(mf.name.StartsWith("Leaf_")||mf.name.StartsWith("Seal_")){var t=mf.transform;moved[t]=t.position;float side=Mathf.Sign(door.InverseTransformPoint(mf.GetComponent<Renderer>().bounds.center).x);t.position-=door.right*side*1.22f;}Physics.SyncTransforms();bool closedBlocks=blocked();foreach(var kv in moved)kv.Key.position=kv.Value;Physics.SyncTransforms();results.Add(new{name=door.name,openClear,closedBlocks});}}finally{EditorSceneManager.OpenScene(s.path);}File.WriteAllText(O+"door_validation.json",JsonConvert.SerializeObject(results,Formatting.Indented));return results;}
}
